import { ArrowRight } from "lucide-react";
import type { ComponentProps, ElementType, ReactNode } from "react";
import { cn } from "./lib/cn";
import { StageScope } from "./stage-scope";
import "./block-concept.css";

/**
 * Marketing blocks share one voice: monochrome from the system tokens, Geist
 * display with two-tone titles, ink actions, ruled sections and ember only for
 * focus. Blocks follow the page theme, and the Caliper UI controls inside them too.
 */

export type BlockAction = { label: string; href?: string; onClick?: () => void };

/**
 * A full-bleed band. The section is the container, so everything inside lays
 * out by the block's own width; `block-inner` holds the measure and rhythm.
 * `backdrop` paints behind the content edge to edge (grid lines, a tone).
 */
export function BlockRoot({
  as: Tag = "section",
  width = "default",
  backdrop,
  tone,
  className,
  innerClassName,
  children,
  ...props
}: Omit<ComponentProps<"section">, "ref"> & {
  /** The band's element; a site footer is a footer. */
  as?: "section" | "footer" | "div";
  /** default 1240px · narrow 960px · wide 1440px. */
  width?: "default" | "narrow" | "wide";
  backdrop?: ReactNode;
  /** A band tone: the page colour or the sunken colour. */
  tone?: "page" | "sunken" | "ink";
  innerClassName?: string;
}) {
  return (
    <Tag data-slot="block" data-tone={tone} className={cn("@container relative isolate overflow-clip", className)} {...props}>
      {backdrop}
      <div data-slot="block-inner" data-width={width} className={innerClassName}>
        {children}
      </div>
    </Tag>
  );
}

export function BlockEyebrow({ className, ...props }: ComponentProps<"p">) {
  return <p data-slot="block-eyebrow" className={className} {...props} />;
}

/** A display heading in the block face. size 1 is the hero headline. */
export function BlockTitle({
  as: Tag = "h2",
  size = 2,
  className,
  ...props
}: ComponentProps<"h2"> & { as?: "h1" | "h2" | "h3"; size?: 1 | 2 | 3 }) {
  return <Tag data-slot="block-title" data-size={size} className={className} {...props} />;
}

/** The second tone of a title: these words land in grey. */
export function BlockEm({ className, ...props }: ComponentProps<"em">) {
  return <em data-slot="block-em" className={className} {...props} />;
}

export function BlockLead({ className, ...props }: ComponentProps<"p">) {
  return <p data-slot="block-lead" className={className} {...props} />;
}

/**
 * The section opening every block shares: eyebrow, title and lead. `split`
 * sets the lead beside the title on wide blocks; `center` stacks it centred.
 */
export function BlockHeader({
  eyebrow,
  title,
  lead,
  align = "start",
  aside,
  headingLevel = 2,
  className,
}: {
  eyebrow?: ReactNode;
  title: ReactNode;
  lead?: ReactNode;
  align?: "start" | "center" | "split";
  /** 1 when the block opens the page, e.g. a pricing page. */
  headingLevel?: 1 | 2;
  /** Sits at the end of the header row, e.g. a period toggle. */
  aside?: ReactNode;
  className?: string;
}) {
  return (
    <header data-slot="block-header" data-align={align} className={className}>
      <div data-slot="block-header-title">
        {eyebrow && <BlockEyebrow>{eyebrow}</BlockEyebrow>}
        <BlockTitle as={headingLevel === 1 ? "h1" : "h2"}>{title}</BlockTitle>
      </div>
      {(lead || aside) && (
        <div data-slot="block-header-aside">
          {lead && <BlockLead>{lead}</BlockLead>}
          {aside}
        </div>
      )}
    </header>
  );
}

export function BlockActions({
  primary,
  secondary,
  className,
  block = false,
}: {
  primary?: BlockAction;
  secondary?: BlockAction;
  className?: string;
  /** Full-width actions, e.g. on phones. */
  block?: boolean;
}) {
  if (!primary && !secondary) return null;
  return (
    <div data-slot="block-actions" className={cn("flex flex-wrap gap-3", block && "@max-[520px]:grid @max-[520px]:grid-cols-1", className)}>
      {primary && <BlockButton action={primary} kind="primary" arrow />}
      {secondary && <BlockButton action={secondary} kind="secondary" />}
    </div>
  );
}

export function BlockButton({ action, kind = "primary", arrow = false, link: Link = "a" }: { action: BlockAction; kind?: "primary" | "secondary"; arrow?: boolean; /** The element for a link action, e.g. your router's Link. */ link?: ElementType }) {
  const shared = { "data-slot": "block-button", "data-kind": kind } as const;
  const content = (
    <>
      {action.label}
      {arrow && <ArrowRight aria-hidden="true" data-slot="block-button-arrow" className="size-4" />}
    </>
  );
  return action.href ? (
    <Link href={action.href} {...shared}>
      {content}
    </Link>
  ) : (
    <button type="button" onClick={action.onClick} {...shared}>
      {content}
    </button>
  );
}

export function BlockCard({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="block-card" className={className} {...props} />;
}

export function BlockChip({ className, ...props }: ComponentProps<"span">) {
  return <span data-slot="block-chip" className={className} {...props} />;
}

/**
 * A product artefact on a stage: a dotted tonal panel holding a framed window, with an optional floating note that overlaps the
 * window's corner on wide blocks and sits beneath it on narrow ones.
 */
export function BlockStage({
  title,
  floating,
  bare = false,
  className,
  children,
}: {
  /** Shown in the window bar, e.g. "halden.app/close". */
  title?: string;
  floating?: ReactNode;
  /** No window frame: the children bring their own surfaces. */
  bare?: boolean;
  className?: string;
  children: ReactNode;
}) {
  return (
    <div data-slot="block-stage" className={className}>
      {bare ? (
        <StageScope>{children}</StageScope>
      ) : (
        <div data-slot="block-window">
          <div data-slot="block-window-bar" aria-hidden={title ? undefined : true}>
            <span data-slot="block-window-dots" aria-hidden="true"><i /><i /><i /></span>
            {title && <span data-slot="block-window-title">{title}</span>}
          </div>
          <div data-slot="block-window-body"><StageScope>{children}</StageScope></div>
        </div>
      )}
      {floating && <div data-slot="block-float">{floating}</div>}
    </div>
  );
}

/** Company names set as type in a quiet row; swap in SVG marks in production. */
export function BlockLogos({ label, logos, className }: { label?: string; logos: readonly string[]; className?: string }) {
  return (
    <div data-slot="block-logos" className={className}>
      {label && <p data-slot="block-logos-label">{label}</p>}
      <ul aria-label={label ?? "Customers"}>
        {logos.map((logo) => (
          <li key={logo}>{logo}</li>
        ))}
      </ul>
    </div>
  );
}

/** Initials from a name, in the block's highlight tones. */
export function BlockInitials({ name, size = 36, tone, className }: { name: string; size?: number; tone?: number; className?: string }) {
  const words = name.trim().split(/\s+/u);
  const initials = ((words[0]?.[0] ?? "") + (words.length > 1 ? (words[words.length - 1]?.[0] ?? "") : "")).toUpperCase();
  return (
    <span data-slot="block-initials" data-tone={tone === undefined ? undefined : tone % 4} aria-hidden="true" className={className} style={{ width: size, height: size, fontSize: Math.round(size / 2.8) }}>
      {initials}
    </span>
  );
}

export type BlockStat = { value: ReactNode; label: string };

"use client";

import { Menu, X } from "lucide-react";
import { useEffect, useId, useRef, useState, type ElementType, type ReactNode } from "react";
import { BlockButton, type BlockAction } from "./block-concept";
import { cn } from "./lib/cn";
import "./shared/site-header.css";
import "./block-nav.css";

export type BlockNavLink = { label: string; href: string; current?: boolean };

// Whole class names, so Tailwind sees them.
const folds = {
  860: { nav: "@[860px]:block", row: "@[860px]:flex", menu: "@[860px]:hidden" },
  1180: { nav: "@[1180px]:block", row: "@[1180px]:flex", menu: "@[1180px]:hidden" },
};

/**
 * The site header page templates share. It sits on the page colour, gains a
 * hairline and frost once the page scrolls, keeps the primary action in
 * reach, and on narrow pages folds the links into a menu disclosure that
 * closes with Escape and returns focus to its button.
 */
export function BlockNav({
  brand,
  brandHref = "/",
  brandLabel,
  logo,
  nav = [],
  signIn,
  primary,
  aside,
  link: Link = "a",
  foldAt = 860,
  className,
}: {
  brand: string;
  brandHref?: string;
  /** The home link's accessible name when the visible brand is short, e.g. "Halden home". */
  brandLabel?: string;
  /** A mark set before the brand name; the name stays the accessible label. */
  logo?: ReactNode;
  nav?: readonly BlockNavLink[];
  signIn?: BlockAction;
  primary?: BlockAction;
  /** Extra controls before the actions, e.g. a theme switch or search. */
  aside?: ReactNode;
  /** The element for the brand and nav links, e.g. your router's Link, so moving between pages stays in the app. */
  link?: ElementType;
  /** The header width (px) the links and actions need to sit in one row; narrower, they fold into the menu. 1180 suits six or more links beside extra controls. */
  foldAt?: keyof typeof folds;
  className?: string;
}) {
  const id = useId();
  const sentinel = useRef<HTMLDivElement>(null);
  const menuButton = useRef<HTMLButtonElement>(null);
  const [scrolled, setScrolled] = useState(false);
  const [menu, setMenu] = useState(false);
  const fold = folds[foldAt];

  useEffect(() => {
    const top = sentinel.current;
    if (!top) return;
    const observer = new IntersectionObserver(([entry]) => setScrolled(!entry!.isIntersecting));
    observer.observe(top);
    return () => observer.disconnect();
  }, []);

  return (
    <>
      <div ref={sentinel} aria-hidden="true" className="absolute top-0 h-px w-px" />
      <header data-slot="site-header" data-scrolled={scrolled || undefined} className={cn("sticky top-0 z-20", className)}>
        <div data-slot="block-nav-row">
          <Link href={brandHref} aria-label={brandLabel} data-slot="block-nav-brand" className={cn(logo && "inline-flex items-center gap-2.5")}>{logo}{brand}</Link>
          {nav.length > 0 && (
            <nav aria-label="Site" className={cn("hidden", fold.nav)}>
              <ul data-slot="block-nav-list">
                {nav.map((item) => (
                  <li key={item.href}>
                    <Link href={item.href} aria-current={item.current ? "page" : undefined} data-slot="block-nav-link">{item.label}</Link>
                  </li>
                ))}
              </ul>
            </nav>
          )}
          <span className={cn("ml-auto hidden items-center gap-2", fold.row)}>
            {aside}
            {signIn && <BlockButton action={signIn} kind="secondary" link={Link} />}
            {primary && <BlockButton action={primary} link={Link} />}
          </span>
          {(nav.length > 0 || signIn) && (
            <button
              ref={menuButton}
              type="button"
              aria-expanded={menu}
              aria-controls={`${id}-menu`}
              onClick={() => setMenu((open) => !open)}
              // Focus stays on the button after it opens the menu, so Escape has to work here too.
              onKeyDown={(event) => event.key === "Escape" && setMenu(false)}
              data-slot="block-button"
              data-kind="secondary"
              className={cn("ml-auto !min-h-11 !px-4", fold.menu)}
            >
              {menu ? <X aria-hidden="true" className="size-4" /> : <Menu aria-hidden="true" className="size-4" />}
              Menu
            </button>
          )}
        </div>
        <div
          id={`${id}-menu`}
          hidden={!menu}
          data-slot="site-menu"
          className={cn("absolute inset-x-0 top-full grid gap-1 border-b border-x border-border bg-[var(--elevated-glass)] px-5 pt-2 pb-6 backdrop-blur-[20px] backdrop-saturate-[1.4] [box-shadow:var(--shadow-overlay),inset_0_1px_0_var(--edge-light)]", fold.menu)}
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              setMenu(false);
              menuButton.current?.focus();
            }
          }}
        >
          {nav.map((item) => (
            <Link key={item.href} href={item.href} aria-current={item.current ? "page" : undefined} onClick={() => setMenu(false)} className="flex h-12 items-center border-b border-[var(--k-line)] text-[17px]">
              {item.label}
            </Link>
          ))}
          {menu && aside && <div className="mt-4 flex flex-wrap items-center gap-2">{aside}</div>}
          <span className="mt-4 grid gap-2">
            {signIn && <BlockButton action={signIn} kind="secondary" link={Link} />}
            {primary && <BlockButton action={primary} link={Link} />}
          </span>
        </div>
      </header>
    </>
  );
}

"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import { Check, Copy } from "lucide-react";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Button, type ButtonProps } from "./button";
import { cn } from "./lib/cn";
import "./shared/action-label.css";
import "./copy-button.css";

/** "rv_live_8Kq2mZt7XcP1vW9yL3nB4f2a" → "rv_live_8K…4f2a". */
export function shortenValue(value: string, head = 10, tail = 4) {
  return value.length <= head + tail + 1 ? value : `${value.slice(0, head)}…${value.slice(-tail)}`;
}

async function writeClipboard(value: string) {
  try {
    await navigator.clipboard.writeText(value);
    return true;
  } catch {
    // Older or locked-down browsers: fall back to a selected textarea.
    const area = document.createElement("textarea");
    area.value = value;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    let ok = false;
    try {
      ok = document.execCommand("copy");
    } catch {
      ok = false;
    }
    area.remove();
    return ok;
  }
}

/**
 * Copies a value and confirms what was copied, shortened in mono, on a small
 * ticket above the button. If the browser blocks the clipboard, the ticket
 * offers the value selected so it can be copied by hand.
 */
export function CopyButton({
  value,
  label,
  display,
  iconOnly = false,
  variant = "secondary",
  size = "sm",
  resetAfterMs = 1800,
  onCopy,
  className,
  children,
}: {
  /** The text written to the clipboard. */
  value: string;
  /** Accessible name, e.g. "Copy live secret key". */
  label: string;
  /** What the ticket shows; defaults to the value shortened in the middle. */
  display?: string;
  iconOnly?: boolean;
  variant?: ButtonProps["variant"];
  size?: Exclude<ButtonProps["size"], "icon">;
  resetAfterMs?: number;
  onCopy?: (ok: boolean) => void;
  className?: string;
  /** Visible label; defaults to “Copy”. */
  children?: ReactNode;
}) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  const fallback = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (state !== "copied") return;
    const timer = setTimeout(() => setState("idle"), resetAfterMs);
    return () => clearTimeout(timer);
  }, [state, resetAfterMs]);

  useEffect(() => {
    if (state === "failed") fallback.current?.select();
  }, [state]);

  async function copy() {
    const ok = await writeClipboard(value);
    setState(ok ? "copied" : "failed");
    onCopy?.(ok);
  }

  const copied = state === "copied";
  const iconClass = { sm: "size-8 rounded-control max-md:size-11", md: undefined, lg: "size-11 rounded-touch" }[size];

  return (
    <span
      data-slot="copy-button"
      className={cn("relative inline-flex", className)}
      onKeyDown={(event) => {
        if (event.key === "Escape" && state !== "idle") setState("idle");
      }}
    >
      <span data-slot="copy-ticket" data-state={state} role={state === "failed" ? "alert" : "status"} aria-live={state === "failed" ? "assertive" : "polite"}>
        {copied && (
          <span data-slot="copy-ticket-body">
            <Check aria-hidden="true" />
            Copied <span className="font-mono text-[11px] opacity-75">{display ?? shortenValue(value)}</span>
          </span>
        )}
        {state === "failed" && (
          <span data-slot="copy-ticket-body" data-tone="error">
            <span>Couldn’t copy. The browser blocked the clipboard; press ⌘C or Ctrl+C.</span>
            <input
              ref={fallback}
              readOnly
              value={value}
              aria-label={`${label}: value to copy by hand`}
              onBlur={() => setState("idle")}
              className="w-full rounded-[6px] bg-background px-2 py-1 font-mono text-xs text-foreground outline-none"
            />
          </span>
        )}
      </span>
      <Button
        variant={variant}
        size={iconOnly ? "icon" : size}
        aria-label={label}
        data-copied={copied}
        className={iconOnly ? iconClass : undefined}
        onClick={copy}
      >
        <span data-slot="copy-icon" data-copied={copied} aria-hidden="true">
          <Copy />
          <Check />
        </span>
        {!iconOnly && (
          <span data-slot="action-labels">
            <span data-slot="action-label" data-active={!copied}>{children ?? "Copy"}</span>
            <span data-slot="action-label" data-active={copied}>Copied</span>
          </span>
        )}
      </Button>
    </span>
  );
}

"use client";

import { Hourglass, RotateCw, Search as SearchIcon, WifiOff } from "lucide-react";
import { useEffect, useId, useRef, useState, useSyncExternalStore, type ReactNode } from "react";
import { BlockActions, BlockEyebrow, BlockLead, BlockRoot, BlockTitle, type BlockAction } from "./block-concept";
import type { BlockNavLink } from "./block-nav";
import { Button } from "./button";
import { CopyButton } from "./copy-button";
import { Field } from "./field";
import { Input } from "./input";
import { TemplatePage, type TemplateFooter } from "./template-page";
import { Textarea } from "./textarea";
import "./error-template.css";

export type ErrorKind = "404" | "403" | "500" | "503" | "offline" | "expired";

const copy: Record<ErrorKind, { eyebrow: string; title: string; lead: string }> = {
  "404": { eyebrow: "Page not found", title: "That page isn't here", lead: "The link may be old, or the page may have moved. Search, or start from one of these." },
  "403": { eyebrow: "No access", title: "You don't have access to this yet", lead: "This page belongs to a workspace you're not a member of. Ask its owner, or switch to the account that has access." },
  "500": { eyebrow: "Something broke", title: "This page didn't load", lead: "It's our fault, not yours. Nothing you did was lost. Try again, and if it keeps happening, send us the reference below." },
  "503": { eyebrow: "Planned maintenance", title: "We're upgrading the database", lead: "Everything you saved is safe. The site is read-only until the work finishes." },
  offline: { eyebrow: "No connection", title: "You're offline", lead: "Check your Wi-Fi or mobile data. This page will notice when you're back." },
  expired: { eyebrow: "Link expired", title: "That link has expired", lead: "For your security, links in our emails work for 30 minutes. Send yourself a new one." },
};

const online = {
  subscribe(notify: () => void) {
    window.addEventListener("online", notify);
    window.addEventListener("offline", notify);
    return () => {
      window.removeEventListener("online", notify);
      window.removeEventListener("offline", notify);
    };
  },
  get: () => navigator.onLine,
  server: () => true,
};

function useMinutesLeft(until?: string) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!until) return;
    const timer = window.setInterval(() => setNow(Date.now()), 30_000);
    return () => window.clearInterval(timer);
  }, [until]);
  return until ? Math.max(0, Math.ceil((Date.parse(until) - now) / 60_000)) : null;
}

const clock = (iso: string) => new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit", timeZoneName: "short" }).format(new Date(iso));

/**
 * The pages people land on when something goes wrong, each with the way
 * out that fits: search for a missing page, ask for access, retry with a
 * reference to quote, wait out maintenance with a time, notice when the
 * connection returns, or send a fresh link. Built only from the Free blocks.
 */
export function ErrorTemplate({
  kind,
  brand,
  nav,
  signIn,
  primary,
  title,
  lead,
  actions,
  suggestions = [],
  onSearch,
  signedInAs,
  onRequestAccess,
  reference,
  onRetry,
  statusHref,
  until,
  onResend,
  isOnline,
  footer,
  className,
}: {
  kind: ErrorKind;
  brand: string;
  nav?: readonly BlockNavLink[];
  signIn?: BlockAction;
  primary?: BlockAction;
  title?: string;
  lead?: string;
  /** Usually "Go home" and a quiet "Go back". */
  actions?: { primary?: BlockAction; secondary?: BlockAction };
  /** Places people usually wanted, for 404. */
  suggestions?: readonly { label: string; href: string; description?: string }[];
  /** 404: adds a search; called with the query. */
  onSearch?: (query: string) => void;
  /** 403: the account that was refused, e.g. "dana@forma.studio". */
  signedInAs?: string;
  /** 403: asks the owner. May return a promise; a thrown error is shown. */
  onRequestAccess?: (note: string) => void | Promise<void>;
  /** 500: an ID support can look up. */
  reference?: string;
  /** 500, 503 and offline: try the page again. */
  onRetry?: () => void | Promise<void>;
  /** 500 and 503: the public status page. */
  statusHref?: string;
  /** 503: when maintenance is expected to end, as an ISO date-time. */
  until?: string;
  /** expired: sends a new link. */
  onResend?: () => void | Promise<void>;
  /** offline: override the browser's online state, e.g. in a preview. */
  isOnline?: boolean;
  footer?: TemplateFooter;
  className?: string;
}) {
  const text = copy[kind];
  const browserOnline = useSyncExternalStore(online.subscribe, online.get, online.server);
  const connected = isOnline ?? browserOnline;
  const minutes = useMinutesLeft(kind === "503" ? until : undefined);
  const figure: ReactNode =
    kind === "offline" ? <WifiOff aria-hidden="true" /> : kind === "expired" ? <Hourglass aria-hidden="true" /> : kind;

  return (
    <TemplatePage brand={brand} nav={nav} signIn={signIn} primary={primary} footer={footer} className={className}>
      <BlockRoot width="narrow">
        <div data-slot="error-page" data-kind={kind}>
          <p data-slot="error-figure" aria-hidden="true">{figure}</p>
          <div className="grid gap-5">
            <BlockEyebrow>{text.eyebrow}</BlockEyebrow>
            <BlockTitle as="h1" size={2} className="max-w-[16ch]">
              {kind === "offline" && connected ? "You're back online" : (title ?? text.title)}
            </BlockTitle>
            <BlockLead>
              {kind === "offline" && connected ? "The connection is back. Reload to pick up where you left off." : (lead ?? text.lead)}
              <span className="sr-only">{kind === "offline" || kind === "expired" ? "" : ` Error ${kind}.`}</span>
            </BlockLead>
          </div>

          {kind === "404" && onSearch && <SearchForm onSearch={onSearch} />}
          {kind === "403" && <AccessRequest signedInAs={signedInAs} onRequestAccess={onRequestAccess} />}
          {kind === "500" && <Retry onRetry={onRetry} reference={reference} statusHref={statusHref} />}
          {kind === "503" && (
            <div data-slot="error-panel" role="status">
              {until ? (
                <p className="m-0 text-[15px]">
                  {minutes && minutes > 0 ? (
                    <>
                      Back in about <b className="font-medium">{minutes} {minutes === 1 ? "minute" : "minutes"}</b>, at {clock(until)}.
                    </>
                  ) : (
                    "The work should be finished. Try again."
                  )}
                </p>
              ) : (
                <p className="m-0 text-[15px]">We’ll be back shortly.</p>
              )}
              <div className="flex flex-wrap gap-2">
                {onRetry && <RetryButton onRetry={onRetry} label="Check again" />}
                {statusHref && <a href={statusHref} data-slot="block-button" data-kind="secondary">Follow on the status page</a>}
              </div>
            </div>
          )}
          {kind === "offline" && (
            <div data-slot="error-panel" role="status" data-online={connected || undefined}>
              <p className="m-0 flex items-center gap-2 text-[15px]">
                <span data-slot="error-dot" aria-hidden="true" />
                {connected ? "Connected" : "Waiting for a connection…"}
              </p>
              {onRetry && <RetryButton onRetry={onRetry} label={connected ? "Reload page" : "Try anyway"} />}
            </div>
          )}
          {kind === "expired" && <Resend onResend={onResend} />}

          {(actions?.primary || actions?.secondary) && <BlockActions primary={actions.primary} secondary={actions.secondary} />}

          {suggestions.length > 0 && (
            <nav aria-label="Suggested pages" data-slot="error-suggestions">
              <ul>
                {suggestions.map((item) => (
                  <li key={item.href}>
                    <a href={item.href}>
                      <span className="text-[16px] font-medium">{item.label}</span>
                      {item.description && <span className="text-[14px] text-[var(--k-muted)]">{item.description}</span>}
                    </a>
                  </li>
                ))}
              </ul>
            </nav>
          )}
        </div>
      </BlockRoot>
    </TemplatePage>
  );
}

function SearchForm({ onSearch }: { onSearch: (query: string) => void }) {
  const [query, setQuery] = useState("");
  return (
    <form
      role="search"
      className="flex max-w-md flex-wrap gap-2"
      onSubmit={(event) => {
        event.preventDefault();
        if (query.trim()) onSearch(query.trim());
      }}
    >
      <Input aria-label="Search the site" type="search" placeholder="Search the site" value={query} onChange={(event) => setQuery(event.target.value)} leading={<SearchIcon aria-hidden="true" className="size-4" />} className="w-auto min-w-0 flex-1 basis-56" />
      <Button type="submit" variant="secondary">Search</Button>
    </form>
  );
}

function RetryButton({ onRetry, label = "Try again" }: { onRetry: () => void | Promise<void>; label?: string }) {
  const [busy, setBusy] = useState(false);
  return (
    <Button
      loading={busy}
      onClick={async () => {
        setBusy(true);
        try {
          await onRetry();
        } finally {
          setBusy(false);
        }
      }}
    >
      <RotateCw aria-hidden="true" />
      {label}
    </Button>
  );
}

function Retry({ onRetry, reference, statusHref }: { onRetry?: () => void | Promise<void>; reference?: string; statusHref?: string }) {
  const [tries, setTries] = useState(0);
  const [busy, setBusy] = useState(false);
  return (
    <div data-slot="error-panel">
      {reference && (
        <div className="flex flex-wrap items-center gap-3">
          <span className="text-[13px] text-[var(--k-muted)]">Reference</span>
          <code data-slot="error-reference">{reference}</code>
          <CopyButton value={reference} label="Copy reference" variant="secondary" />
        </div>
      )}
      <div className="flex flex-wrap items-center gap-3">
        {onRetry && (
          <Button
            loading={busy}
            onClick={async () => {
              setBusy(true);
              try {
                await onRetry();
              } catch {
                setTries((count) => count + 1);
              } finally {
                setBusy(false);
              }
            }}
          >
            <RotateCw aria-hidden="true" />
            Try again
          </Button>
        )}
        {statusHref && <a href={statusHref} className="text-[14px] underline underline-offset-4">Check system status</a>}
      </div>
      <p role="status" className="m-0 min-h-5 text-[13px] text-[var(--k-muted)]">
        {tries > 0 && `Still not working after ${tries} ${tries === 1 ? "try" : "tries"}. ${tries > 1 && reference ? "Send the reference to support and we'll look." : "Give it a minute."}`}
      </p>
    </div>
  );
}

function AccessRequest({ signedInAs, onRequestAccess }: { signedInAs?: string; onRequestAccess?: (note: string) => void | Promise<void> }) {
  const [note, setNote] = useState("");
  const [state, setState] = useState<"idle" | "sending" | "sent">("idle");
  const [error, setError] = useState<string>();
  const done = useRef<HTMLParagraphElement>(null);
  const id = useId();
  useEffect(() => {
    if (state === "sent") done.current?.focus();
  }, [state]);
  if (!onRequestAccess) return signedInAs ? <p className="m-0 text-[15px] text-[var(--k-muted)]">Signed in as <b className="font-medium text-[var(--k-ink)]">{signedInAs}</b>.</p> : null;
  if (state === "sent")
    return (
      <div data-slot="error-panel">
        <p ref={done} tabIndex={-1} role="status" className="m-0 text-[15px] outline-none">
          Request sent. The owner will get an email, and you’ll hear back at <b className="font-medium">{signedInAs ?? "your address"}</b>.
        </p>
      </div>
    );
  return (
    <form
      data-slot="error-panel"
      aria-labelledby={`${id}-title`}
      onSubmit={async (event) => {
        event.preventDefault();
        setState("sending");
        setError(undefined);
        try {
          await onRequestAccess(note.trim());
          setState("sent");
        } catch (reason) {
          setError(reason instanceof Error ? reason.message : "The request did not send. Try again.");
          setState("idle");
        }
      }}
    >
      <p id={`${id}-title`} className="m-0 text-[15px]">
        Signed in as <b className="font-medium">{signedInAs}</b>
      </p>
      <Field label="Note to the owner" optional error={error} description="Say what you need it for.">
        {(props) => <Textarea {...props} value={note} onChange={(event) => setNote(event.target.value)} disabled={state === "sending"} rows={2} />}
      </Field>
      <div className="flex flex-wrap gap-2">
        <Button type="submit" loading={state === "sending"}>Request access</Button>
      </div>
    </form>
  );
}

function Resend({ onResend }: { onResend?: () => void | Promise<void> }) {
  const [wait, setWait] = useState(0);
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);
  useEffect(() => {
    if (wait <= 0) return;
    const timer = window.setTimeout(() => setWait((left) => left - 1), 1000);
    return () => window.clearTimeout(timer);
  }, [wait]);
  if (!onResend) return null;
  return (
    <div data-slot="error-panel">
      <div className="flex flex-wrap items-center gap-3">
        <Button
          loading={busy}
          disabled={wait > 0}
          onClick={async () => {
            setBusy(true);
            try {
              await onResend();
              setSent(true);
              setWait(30);
            } finally {
              setBusy(false);
            }
          }}
        >
          {wait > 0 ? `Send again in 0:${String(wait).padStart(2, "0")}` : sent ? "Send another link" : "Send a new link"}
        </Button>
      </div>
      <p role="status" className="m-0 min-h-5 text-[13px] text-[var(--k-muted)]">{sent ? "A new link is on its way. It works for 30 minutes." : ""}</p>
    </div>
  );
}

"use client";
